text:
  &[selected]:not(.editing),
  &:where(.invalid-address, .key-issue)[selected]:not(.editing) {
    color: var(--selected-item-text-color);
    background-color: var(--selected-item-color);
  }

  & label {
    -moz-user-focus: none;
    cursor: default;
    margin-inline: 0;
  }

  & label,
  & hbox {
    pointer-events: none;
  }

  & hbox:not([hidden]) {
    display: flex;
  }

  &[selected]:not(.editing) .pill-indicator {
    fill: var(--selected-item-color);
  }
}

.pill-indicator {
  -moz-context-properties: fill, stroke;
  fill: currentColor;
  stroke: Field;
  inline-size: 8px;
  margin-inline-end: -8px;
  margin-block-end: 1em;
  transition:
    fill 0.2s ease,
    stroke 0.2s ease;

  :root[lwt-tree] & {
    stroke: var(--toolbar-field-background-color);
  }
}

.address-identity-recipient {
  margin-inline-end: 8px;
  display: flex;
}
